"use strict";(self.webpackChunksalat_e_mustaqeem_client=self.webpackChunksalat_e_mustaqeem_client||[]).push([[5790],{35790:a=>{a.exports=JSON.parse('{"meta":{"title":"Aplikasi Waktu Salat Salat-e-Mustaqeem untuk iPhone dan Android - iMuslim Life","description":"Salat-e-Mustaqeem 1.09.1 untuk iPhone, Android, Apple Watch, dan Galaxy Watch: Mushaf berhias, Al-Qur\u2019an setelah Salat, Azan penuh, Journey untuk keluarga, widget, dan Siri. Gratis dan tanpa iklan."},"store":{"appleSmall":"Unduh di","appleBig":"App Store","playSmall":"Dapatkan di","playBig":"Google Play"},"hero":{"iconAlt":"Ikon aplikasi Salat-e-Mustaqeem","lede":"Waktu salat, Al-Qur\'an kata demi kata, dan beranda tenang yang mengikuti langit. Di iPhone, ponsel Android, Apple Watch, dan Alexa.","facts":"Gratis \xb7 Tanpa iklan \xb7 Bisa offline \xb7 English, \u0627\u0644\u0639\u0631\u0628\u064a\u0629, \u0627\u0631\u062f\u0648","alts":["Lembar kata di pembaca Al-Qur\'an","Tab salat berbentuk jam matahari","Beranda N\u016br dengan hitung mundur salat berikutnya"]},"whatsNew":{"eyebrow":"Yang baru di {{v}}","h2":"Al-Qur\u2019an, bercahaya","lede":"Mushaf untuk dibaca, dipelajari, dan dihafalkan, serta sedikit Al-Qur\u2019an setelah setiap salat.","items":[{"title":"Mushaf berhias","text":"Baca di halaman Mushaf dengan garis hasyiyah, tanda rukuk, rub\u2018 al-hizb, manzil, dan sajdah, serta kata-kata pembuka setiap juz berwarna emas."},{"title":"Baca, Kata, dan Mushaf","text":"Tiga jalan menuju halaman yang sama: teks mengalir, setiap kata dengan artinya, atau Mushaf cetak. Ketuk kata mana pun untuk melihat arti dan tajwidnya."},{"title":"Al-Qur\u2019an setelah Salat","text":"Khatamkan Al-Qur\u2019an sedikit demi sedikit setelah setiap salat, dalam 7, 15, 30, atau 60 hari."},{"title":"Qur\u2019anku dan Info Surah","text":"Penanda, catatan, dan koleksi di satu tempat, serta pengantar setiap surah dari Tafsir Ibnu Katsir."},{"title":"Ayat dan Doa Hari Ini","text":"Ayat yang sama untuk seluruh Umat setiap hari, kini juga di layar utama dan layar kunci, offline selama seminggu."},{"title":"Radio Al-Qur\u2019an dan Bagikan ayat","text":"Lantunan tanpa putus dari qari favorit Anda, dan ayat mana pun dibagikan sebagai gambar yang indah."}]},"quran":{"eyebrow":"Al-Qur\'an, kata demi kata","h2":"Pahami setiap kata yang kamu baca","lede":"Ketuk kata mana pun untuk melihat artinya, cara melafalkannya, dan hukum tajwidnya. Dengarkan setiap ayat menyala, dan lanjutkan tepat di tempat terakhir.","bullets":[{"b":"77.429 kata","t":"dengan arti dalam bahasa Inggris dan Urdu serta transliterasi."},{"b":"Dengarkan satu kata saja,","t":"dipotong dari bacaan, bahkan offline."},{"b":"Surah lengkap offline,","t":"diunduh atau disimpan saat didengar, di Unduhan & penyimpanan."},{"b":"Mendengar di latar belakang","t":"dengan kontrol Layar Kunci, kecepatan, dan pewaktu tidur."},{"b":"Lebih dari 30 qari,","t":"termasuk Maher Al-Muaiqly, Husary, Abdul Basit, dan al-Tablawi."},{"b":"Lanjutkan membaca","t":"di ayat yang tepat, dan lompat ke surah atau juz mana pun dengan namanya."}],"alts":["Tata letak Kata, dengan arti di bawah setiap kata","Lembar untuk satu kata","Bacaan terpandu di Surah Yasin"]},"prayer":{"eyebrow":"Salat, sepanjang hari","h2":"Jangan lewatkan satu salat pun","lede":"Harimu sebagai jam matahari, beranda yang mengikuti langit, dan pengingat yang tepat waktu, dengan azan lengkap dari muazin pilihanmu.","bullets":[{"b":"Pengingat azan lengkap","t":"dari tujuh muazin, dengan azan khusus Subuh."},{"b":"Jalan salat hari ini:","t":"ketuk salat setelah kamu mengerjakannya, atau tambahkan ke qada."},{"b":"Azan lengkap di iPhone,","t":"melampaui batas 30 detik, di iOS 26 (Eksperimental)."},{"b":"Waktumu sendiri:","t":"sesuaikan salat mana pun dan tambahkan pengingat sebelum azan."},{"b":"Enam tema beranda","t":"dan mode gelap penuh, nyaman di mata saat Subuh."},{"b":"Siap bepergian:","t":"waktu salat mengikutimu ke kota baru, dan berjalan tanpa koneksi."},{"b":"Kompas kiblat","t":"yang memberi tahu arah untuk menghadap."}],"alts":["Tab salat berbentuk jam matahari","Beranda N\u016br","Beranda N\u016br dalam mode gelap"]},"shots":{"eyebrow":"Versi {{v}}","h2":"Tangkapan Layar Aplikasi","lede":"Geser untuk melihat Salat-e-Mustaqeem yang baru.","label":"Tangkapan layar aplikasi","prev":"Tangkapan sebelumnya","next":"Tangkapan berikutnya","alts":["Beranda dengan salat berikutnya dan jalan salat hari ini","Jam matahari: semua waktu salat dalam satu cincin","Surah Yasin dalam tata letak Kata","Lembar kata: arti, suara, dan tajwid satu kata","Doa dikelompokkan menurut waktu","Penghitung zikir setelah setiap salat","Kalkulator zakat dengan nisab hari ini","Kompas kiblat dan jarak ke Makkah","Beranda dalam mode gelap","Pembaca Al-Qur\'an dalam mode gelap"]},"watch":{"eyebrow":"Baru \xb7 Apple Watch","h2":"Waktu salat di pergelangan tanganmu","lede":"Salat berikutnya di muka jam, langit hari ini sebagai jam matahari, penunjuk kiblat, dan tasbih yang dihitung dengan Digital Crown. Termasuk dalam aplikasi iPhone.","alt":"Apple Watch: {{title}}","items":[{"title":"Komplikasi","text":"Salat berikutnya di muka jam"},{"title":"Hari ini","text":"Jam matahari dengan langit yang hidup"},{"title":"Waktu","text":"Kelima salat sekilas"},{"title":"Kiblat","text":"Putar sampai terkunci, dengan ketukan lembut"},{"title":"Tasbih","text":"33 butir dengan crown atau ketukan"}]},"everywhere":{"eyebrow":"Di mana pun kamu berada","h2":"Zikir, ke mana pun kamu memandang","siriH":"Tanya saja Siri","siriSub":"Tanpa pengaturan, dalam bahasa Inggris dan Arab:","cards":[{"title":"Hitung mundur di Layar Kunci","text":"Hitung mundur salat di Layar Kunci dan Dynamic Island. Ketuk \u201cSudah salat\u201d untuk mencatat salatmu."},{"title":"Widget beranda","text":"Widget zamrud dan emas di iPhone dan Android, kini menampilkan kotamu."},{"title":"Alexa: Muslim Companion","text":"Echo-mu mengumandangkan azan setiap waktu salat, membacakan surah apa pun, dan membimbing hafalanmu."}],"alexaLink":"Jelajahi skill Alexa \u2192","phrases":["When is the next prayer in Salat-e-Mustaqeem","When is Asr in Salat-e-Mustaqeem","Today\u2019s prayer times in Salat-e-Mustaqeem","Where is the Qibla in Salat-e-Mustaqeem","What\u2019s the Islamic date in Salat-e-Mustaqeem","When is iftar in Salat-e-Mustaqeem"]},"features":{"eyebrow":"Semua di dalamnya","h2":"Satu aplikasi untuk hari ibadahmu","items":[{"title":"Pengingat azan","text":"Azan, bip, atau senyap per salat."},{"title":"Kiblat","text":"Kompas yang mengarahkanmu ke Ka\'bah."},{"title":"Tafsir","text":"Tafsir jelas dan mudah dibaca per ayat."},{"title":"Mode gelap","text":"Sepuluh warna aksen, enam tema beranda."},{"title":"Tiga bahasa","text":"Inggris, Arab, dan Urdu."},{"title":"Bisa offline","text":"Waktu salat dan Al-Qur\'an tanpa koneksi."}]},"faq":{"eyebrow":"Pertanyaan","h2":"Pertanyaan yang sering diajukan","items":[{"q":"Seberapa akurat waktu salatnya?","a":"Waktu dihitung untuk lokasimu yang tepat. Pilih metode perhitungan dan mazhab Asar (Syafi\'i atau Hanafi) yang diikuti masjidmu. Saat bepergian, waktu dan pengingat ikut bersamamu."},{"q":"Apakah aplikasi bisa offline?","a":"Ya. Saat tanpa koneksi, waktu salat dihitung di ponsel, dan teks Al-Qur\'an, arti kata, serta ayat yang sudah kamu dengar tetap tersedia offline."},{"q":"Apakah Salat-e-Mustaqeem gratis?","a":"Ya. Semua fitur gratis, tanpa iklan dan tanpa pembelian dalam aplikasi. Kami yakin alat bantu salat harus terbuka untuk semua."},{"q":"Perangkat apa yang didukung?","a":"iPhone dan iPad dengan iOS 17 atau lebih baru, Apple Watch dengan watchOS 11 atau lebih baru (disertakan dengan aplikasi iPhone), ponsel Android 7.0 atau lebih baru, serta Galaxy Watch dan jam Wear OS lainnya (disertakan dengan aplikasi Android)."},{"q":"Bagaimana cara menambah widget?","a":"Di iPhone, tekan lama Layar Utama, ketuk Edit, lalu Tambah Widget, dan cari Salat-e-Mustaqeem. Di Android, tekan lama layar utama, ketuk Widget, dan pilih Salat-e-Mustaqeem. Pilih Salat Berikutnya, Salat Hari Ini, atau Salat Saat Ini."},{"q":"Bahasa apa saja di aplikasi?","a":"Aplikasi tersedia dalam bahasa Inggris, Arab, dan Urdu (Pengaturan \u2192 Bahasa), dengan tata letak kanan-ke-kiri. Arti kata dalam bahasa Inggris dan Urdu, dan Siri memahami bahasa Inggris dan Arab."},{"q":"Apakah ada skill Alexa?","a":"Ya, Muslim Companion. Ia mengumandangkan azan di Echo-mu setiap waktu salat, membacakan surah apa pun, membimbing hafalan, dan menemanimu di bulan Ramadan. Ucapkan \u201cAlexa, open Muslim Companion\u201d."}],"idea":"Punya ide untuk versi berikutnya?","suggest":"Usulkan fitur"},"download":{"h2":"Unduh Salat-e-Mustaqeem","lede":"Gratis, tanpa iklan. Untuk iPhone, iPad, Apple Watch, dan Android.","qr":["Pindai untuk App Store","Pindai untuk Google Play"],"ayah":"Tunjukilah kami jalan yang lurus. \u2014 Al-Fatihah 1:6"},"seal":{"label":"Versi {{v}}","word":"VERSI"},"releases":{"kicker":"Perjalanan 1.04 \u2192 {{v}}","h2":"Tujuh rilis dalam tiga minggu","tabs":"Rilis","items":[{"summary":"Azan lengkap, aplikasi jam untuk Android, dan Al-Qur\'an tanpa koneksi.","features":[{"tag":"iPhone \xb7 Eksperimental","title":"Azan lengkap","text":"Di iOS 26, azan lengkap berkumandang di setiap waktu salat, bukan potongan 30 detik."},{"tag":"Wear OS","title":"Aplikasi Galaxy Watch","text":"Tile dan komplikasi yang menghitung mundur ke salat berikutnya."},{"tag":"Al-Qur\'an","title":"Surah offline","text":"Unduh surah lengkap, atau simpan yang kamu putar. Kelola di Unduhan & penyimpanan."},{"tag":"Al-Qur\'an","title":"Qari dan terjemahan di pemutar","text":"Pilih dari 33 qari dan dengarkan terjemahan bersama setiap surah."}],"more":"Juga di 1.04: hitung mundur di layar kunci sebelum setiap salat di Android, pintasan aplikasi, pengingat yang didesain ulang, panduan salat beranimasi, dan aplikasi di Mac."},{"summary":"Kisah setiap pekan, dan cara yang lebih tenang untuk belajar doa.","features":[{"tag":"Belajar","title":"Kisah pekanan","text":"Kisah baru setiap pekan dari Sirah, para Nabi, dan para Sahabat, dalam bahasa Inggris dan Urdu."},{"tag":"Al-Qur\'an","title":"Ganti qari di tengah surah","text":"Ubah suara tanpa kehilangan posisi bacaan."},{"tag":"Doa","title":"Doa yang didesain ulang","text":"Doa dikelompokkan menurut waktu, dengan langkah doa ditambahkan ke panduan salat."},{"tag":"Alexa","title":"Echo-mu, dari aplikasi","text":"Atur Muslim Companion dan azannya dari ponselmu."}],"more":"Juga di 1.05: gambar Aktivitas Langsung yang terisi saat waktu salat mendekat, dan panduan widget Android."},{"summary":"Journey: cara lembut bagi seluruh keluarga untuk tumbuh bersama dalam salat.","features":[{"tag":"Keluarga","title":"Journey","text":"Catat salat, waktu Al-Qur\'an, dan zikir sebagai keluarga, dan lihat pelita kalian menyala."},{"tag":"Anak","title":"Rihla dan Masjidku","text":"Anak-anak menjelajahi peta kota-kota Islam dan membangun masjid mereka sendiri seiring salat mereka."},{"tag":"Keluarga","title":"Kuis dan malam kuis","text":"Kuis Islami harian, dan malam kuis bersama lewat SharePlay."},{"tag":"Salat","title":"Waktu salatmu sendiri","text":"Sesuaikan salat mana pun per menit, tambahkan pengingat sebelum azan, dan atur tanggal Hijriah."}],"more":"Juga di 1.06: musim dan episode di Journey, widget Pelita, nisab zakat, serta Tentang & kredit."},{"summary":"Penyempurnaan dan perbaikan, dengan kartu Niyyah segera hadir.","features":[{"tag":"Beranda","title":"Kartu Niyyah","text":"Niat singkat di Beranda untuk memulai hari dengan tujuan."}],"more":""},{"summary":"Kalender Islam baru, mode Perjalanan, dan Kiblat lewat kamera.","features":[{"tag":"Kalender","title":"Kalender Islam","text":"Bulan sabit demi bulan, kartu acara dan pengingat, Tambahkan ke Kalender, dan widget kalender."},{"tag":"Salat","title":"Mode Perjalanan","text":"Memberi tahu saat Anda bepergian dan menawarkan salat qasar dan jamak."},{"tag":"Kiblat","title":"Kiblat dengan kamera","text":"Angkat ponsel Anda dan lihat arah Kiblat di ruangan sekitar Anda."},{"tag":"iPhone \xb7 Android","title":"Sudah salat, di mana saja","text":"Tandai salat dari Layar Kunci, Pusat Kontrol, StandBy, atau pengingatnya langsung."}],"more":"Juga di 1.08: Fokus Salat dan aksi Pintasan, ubin Pengaturan Cepat di Android, menit mindful di Apple Health dan Health Connect, serta lukisan di setiap pengingat salat."},{"summary":"Al-Qur\u2019an, bercahaya: Mushaf untuk dibaca, dipelajari, dan dihafalkan.","features":[{"tag":"Al-Qur\u2019an","title":"Mushaf berhias","text":"Halaman Mushaf dengan garis hasyiyah; ketuk kata mana pun untuk artinya dan hafalkan dari halaman."},{"tag":"Al-Qur\u2019an","title":"Al-Qur\u2019an setelah Salat","text":"Khatamkan Al-Qur\u2019an sedikit demi sedikit setelah setiap salat, dalam 7, 15, 30, atau 60 hari."},{"tag":"Belajar","title":"Qur\u2019anku dan Info Surah","text":"Penanda, catatan, dan koleksi, serta pengantar setiap surah dari Tafsir Ibnu Katsir."},{"tag":"Al-Qur\u2019an","title":"Radio Al-Qur\u2019an","text":"Lantunan tanpa putus dari qari favorit Anda."}],"more":"Juga di 1.09: bagikan ayat mana pun sebagai gambar, Ayat Hari Ini baru untuk seluruh Umat, pencadangan dan sinkronisasi pengaturan dengan akun Anda, serta tampilan jam dan widget Prayer Face baru."},{"summary":"Widget baru, dan kata-kata pembuka setiap juz berwarna emas.","features":[{"tag":"Widget","title":"Ayat dan Doa Hari Ini","text":"Di layar utama dan layar kunci, iPhone dan Android, offline selama seminggu."},{"tag":"Android","title":"Widget Prayer Face","text":"Tampilan tab Salat di layar utama Anda dalam tiga ukuran, dengan pemilih tampilan."},{"tag":"Al-Qur\u2019an","title":"Pembuka juz berhias","text":"Kata-kata yang menjadi nama setiap juz bersinar di Baca, Kata, dan Mushaf."},{"tag":"Al-Qur\u2019an","title":"Putar dari ayat yang dipilih","text":"Ayat yang dipilih kini diputar dari ayat itu, bukan dari awal surah."}],"more":"Juga di 1.09.1: tanda Mushaf untuk rukuk, rub\u2018 al-hizb, manzil, dan sajdah; seperempat juz diberi nama; serta mikrofon dan lokasi bersifat opsional, sehingga Android TV, mobil, dan tablet tetap bisa memakai aplikasi."}]},"coming":{"badge":"Segera hadir","eyebrow":"Dalam perjalanan","h2":"Segera hadir","lede":"Sudah dibuat, dan sedang diuji sebelum sampai ke ponselmu.","items":[{"title":"Tasm\u012b\u2018","text":"Bacalah dengan lantang dan lihat kata mana yang benar, dengan huruf Qaida untuk pemula."},{"title":"Pelatih Hifz","text":"Hafalkan satu halaman demi satu halaman, dengan tajwid berwarna."}]}}')}}]);